/** @jsxImportSource kerfjs */
import { computed, mount, selector, signal } from 'kerfjs';
import { each } from 'kerfjs/list';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };

function createRow(record: RecordData) {
  return { id: record.id, label: signal(record.label) };
}

type Row = ReturnType<typeof createRow>;

const fruit = ['Apricot', 'Blueberry', 'Cherry'];
const options = fruit.map(value => ({ value, label: value }));

type CommitHandler = (...args: unknown[]) => void;
const Picker = Combobox as unknown as (props: {
  id: string;
  name: string;
  label: string;
  options: typeof options;
  suggestions: string[];
  onCommit: CommitHandler;
}) => ReturnType<typeof Combobox>;
const wirePicker = wireComboboxes as unknown as (
  host: HTMLElement,
  options: { onCommit: CommitHandler }
) => unknown;

function commitValue(value: unknown): string | undefined {
  if (typeof value === 'string') return value;
  if (value instanceof CustomEvent) return commitValue(value.detail);
  if (value && typeof value === 'object' && 'value' in value &&
      typeof value.value === 'string') return value.value;
}

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void
) {
  const app = document.createElement('div');
  const inspector = document.createElement('div');
  const list = document.createElement('div');
  app.append(inspector, list);
  root.append(app);

  const counts = { incoming: signal(4), outgoing: signal(7) };
  const activeSource = signal<Source>('incoming');
  const badge = computed(() => `${counts[activeSource.value].value} crates`);
  const stopInspector = mount(inspector, () => (
    <>
      <output data-badge="" title={badge}>{badge}</output>
      <input data-note="" aria-label="Note" />
    </>
  ));

  const rows = signal<Row[]>([
    { id: 1, label: 'One' },
    { id: 2, label: 'Two' },
    { id: 3, label: 'Three' },
    { id: 4, label: 'Four' }
  ].map(createRow));
  const selectedId = signal(0);
  const isSelected = selector(selectedId);

  function renderRow(row: Row) {
    mark('row');
    const selected = isSelected(row.id);
    const ariaSelected = computed(() => selected.value ? 'true' : 'false');
    return (
      <div role="option" data-key={row.id} data-row={row.id} aria-selected={ariaSelected}>
        <span>{row.label}</span>
        <input aria-label={`Edit record ${row.id}`} />
      </div>
    );
  }

  const stopList = mount(list, () => <>{each(rows.value, renderRow)}</>);
  let disposed = false;
  let stopPicker: (() => void) | undefined;
  let pickerNumber = 0;

  function updateRows(next: Row[]) {
    const input = document.activeElement;
    if (!(input instanceof HTMLInputElement) || !list.contains(input)) {
      rows.value = next;
      return;
    }
    const start = input.selectionStart;
    const end = input.selectionEnd;
    const direction = input.selectionDirection;
    rows.value = next;
    function restore() {
      if (!input.isConnected) return;
      if (document.activeElement === document.body) input.focus({ preventScroll: true });
      if (document.activeElement === input && start !== null && end !== null) {
        input.setSelectionRange(start, end, direction ?? 'none');
      }
    }
    restore();
    queueMicrotask(restore);
  }

  function close() {
    const stop = stopPicker;
    stopPicker = undefined;
    stop?.();
  }

  function open() {
    if (disposed || stopPicker) return;
    const host = document.createElement('div');
    const id = `study-fruit-${++pickerNumber}`;
    app.append(host);
    let active = true;
    let committing = false;

    function commit(...args: unknown[]) {
      if (!active || committing) return;
      const value = args.filter(arg => !(arg instanceof HTMLElement))
        .map(commitValue).find(candidate => candidate !== undefined);
      if (value === undefined || !value.trim()) return;
      committing = true;
      queueMicrotask(() => { committing = false; });
      const input = host.querySelector('input');
      if (input) input.value = '';
      onCommit(value);
    }

    const unmount = mount(host, () => (
      <Picker id={id} name="Fruit" label="Fruit" options={options}
        suggestions={fruit} onCommit={commit} />
    ));
    const unwire = wirePicker(host, { onCommit: commit });
    stopPicker = () => {
      active = false;
      if (typeof unwire === 'function') unwire();
      unmount();
      host.remove();
    };
  }

  return {
    count(source: Source, value: number) {
      if (!disposed) counts[source].value = value;
    },
    mode(source: Source) {
      if (!disposed) activeSource.value = source;
    },
    select(id: number) {
      if (!disposed) selectedId.value = id;
    },
    refetch(records: RecordData[]) {
      if (disposed) return;
      const byId = new Map(rows.value.map(row => [row.id, row]));
      updateRows(records.map(record => {
        const row = byId.get(record.id);
        if (!row) return createRow(record);
        row.label.value = record.label;
        return row;
      }));
    },
    swap() {
      if (disposed || rows.value.length < 2) return;
      const [first, second, ...rest] = rows.value;
      updateRows([second, first, ...rest]);
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      stopList();
      stopInspector();
      app.remove();
    }
  };
}
